mkitem!{mkimpl!{impl < 'll , 'tcx > CguCoverageContext < 'll , 'tcx > { pub (crate) fn new () -> Self { Self { pgo_func_name_var_map : Default :: default () , covfun_section_name : Default :: default () } } # [doc = " Returns the list of instances considered \"used\" in this CGU, as"] # [doc = " inferred from the keys of `pgo_func_name_var_map`."] pub (crate) fn instances_used (& self) -> Vec < Instance < 'tcx > > { self . pgo_func_name_var_map . borrow () . keys () . copied () . collect :: < Vec < _ > > () } }}}
mkitem!{mkimpl!{impl < 'll , 'tcx > CodegenCx < 'll , 'tcx > { pub (crate) fn coverageinfo_finalize (& mut self) { mapgen :: finalize (self) } # [doc = " Returns the section name to use when embedding per-function coverage information"] # [doc = " in the object file, according to the target's object file format. LLVM's coverage"] # [doc = " tools use information from this section when producing coverage reports."] # [doc = ""] # [doc = " Typical values are:"] # [doc = " - `__llvm_covfun` on Linux"] # [doc = " - `__LLVM_COV,__llvm_covfun` on macOS (includes `__LLVM_COV,` segment prefix)"] # [doc = " - `.lcovfun$M` on Windows (includes `$M` sorting suffix)"] fn covfun_section_name (& self) -> & CStr { self . coverage_cx () . covfun_section_name . get_or_init (| | llvm_cov :: covfun_section_name (self . llmod)) } # [doc = " For LLVM codegen, returns a function-specific `Value` for a global"] # [doc = " string, to hold the function name passed to LLVM intrinsic"] # [doc = " `instrprof.increment()`. The `Value` is only created once per instance."] # [doc = " Multiple invocations with the same instance return the same `Value`."] # [doc = ""] # [doc = " This has the side-effect of causing coverage codegen to consider this"] # [doc = " function \"used\", making it eligible to emit an associated covfun record."] fn ensure_pgo_func_name_var (& self , instance : Instance < 'tcx >) -> & 'll llvm :: Value { debug ! ("getting pgo_func_name_var for instance={:?}" , instance) ; let mut pgo_func_name_var_map = self . coverage_cx () . pgo_func_name_var_map . borrow_mut () ; pgo_func_name_var_map . entry (instance) . or_insert_with (| | { let llfn = self . get_fn (instance) ; let mangled_fn_name : & str = self . tcx . symbol_name (instance) . name ; llvm_cov :: create_pgo_func_name_var (llfn , mangled_fn_name) }) } }}}
mkitem!{mkimpl!{impl < 'tcx > CoverageInfoBuilderMethods < 'tcx > for Builder < '_ , '_ , 'tcx > { # [instrument (level = "debug" , skip (self))] fn add_coverage (& mut self , instance : Instance < 'tcx > , kind : & CoverageKind) { let bx = self ; let Some (_coverage_cx) = & bx . cx . coverage_cx else { return } ; let Some (function_coverage_info) = bx . tcx . instance_mir (instance . def) . function_coverage_info . as_deref () else { debug ! ("function has a coverage statement but no coverage info") ; return ; } ; let Some (ids_info) = bx . tcx . coverage_ids_info (instance . def) else { debug ! ("function has a coverage statement but no IDs info") ; return ; } ; match * kind { CoverageKind :: SpanMarker | CoverageKind :: BlockMarker { .. } => unreachable ! ("marker statement {kind:?} should have been removed by CleanupPostBorrowck") , CoverageKind :: VirtualCounter { bcb } if let Some (& id) = ids_info . phys_counter_for_node . get (& bcb) => { let fn_name = bx . ensure_pgo_func_name_var (instance) ; let hash = bx . const_u64 (function_coverage_info . function_source_hash) ; let num_counters = bx . const_u32 (ids_info . num_counters) ; let index = bx . const_u32 (id . as_u32 ()) ; debug ! ("codegen intrinsic instrprof.increment(fn_name={:?}, hash={:?}, num_counters={:?}, index={:?})" , fn_name , hash , num_counters , index ,) ; bx . instrprof_increment (fn_name , hash , num_counters , index) ; } CoverageKind :: VirtualCounter { .. } => { } } } }}}